import React, { useEffect, useRef, useState } from 'react';
import * as THREE from 'three';

const ProductAndServices = () => {
  const mountRef = useRef(null);
  const [scrollY, setScrollY] = useState(0);

  let camera, renderer;

  useEffect(() => {
    // Create the scene, camera, and renderer
    const scene = new THREE.Scene();
    camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
    renderer = new THREE.WebGLRenderer({ antialias: true });

    renderer.setSize(window.innerWidth, window.innerHeight);
    mountRef.current.appendChild(renderer.domElement);

    // Load images as textures and create planes
    const textureLoader = new THREE.TextureLoader();
    const imagePaths = [
      './images/Cricket.jpg', 
      './images/Cricket.jpg',
      './images/Cricket.jpg',
      // Add more image paths
    ];
    
    const planes = [];
    imagePaths.forEach((path, index) => {
      const texture = textureLoader.load(path);
      const geometry = new THREE.PlaneGeometry(5, 3); // Plane size
      const material = new THREE.MeshBasicMaterial({ map: texture });
      const plane = new THREE.Mesh(geometry, material);

      plane.position.y = -index * 5; // Space the planes vertically
      plane.position.z = -10; // Move planes into the scene
      planes.push(plane);
      scene.add(plane);
    });

    camera.position.z = 10;

    // Scroll event handler
    const handleScroll = () => {
      setScrollY(window.scrollY * 0.05); // Adjust scroll speed factor
    };

    window.addEventListener('scroll', handleScroll);

    // Animation function
    const animate = () => {
      requestAnimationFrame(animate);

      // Update plane positions based on scroll
      planes.forEach((plane, index) => {
        plane.position.y = -index * 5 + scrollY;
      });

      renderer.render(scene, camera);
    };
    
    animate();

    // Cleanup
    return () => {
      window.removeEventListener('scroll', handleScroll);
      mountRef.current.removeChild(renderer.domElement);
    };
  }, [scrollY]);

  // Adjust canvas size on window resize
  useEffect(() => {
    const handleResize = () => {
      const width = window.innerWidth;
      const height = window.innerHeight;
      renderer.setSize(width, height);
      camera.aspect = width / height;
      camera.updateProjectionMatrix();
    };

    window.addEventListener('resize', handleResize);
    
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  return (
    <div>
      <div ref={mountRef} style={{ width: '100vw', height: '100vh' }} />
      <div style={{ height: '200vh', backgroundColor: '#f0f0f0' }}>
        {/* Just a tall container to scroll */}
      </div>
    </div>
  );
};

export default ProductAndServices;
